SELECT COUNT(1)
FROM agent_memory_task
WHERE task_type = #{taskType}
  AND session_id = #{sessionId}
  AND status IN ('PENDING', 'RUNNING')
  AND COALESCE(updated_at, created_at, CURRENT_TIMESTAMP) >= DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 30 MINUTE)

SELECT COUNT(1)
FROM agent_memory_task
WHERE task_type = #{taskType}
  AND turn_id = #{turnId}

SELECT COUNT(1)
FROM agent_memory_task
WHERE task_type = #{taskType}
  AND turn_id = #{turnId}
  AND status IN ('PENDING', 'RUNNING')
  AND COALESCE(updated_at, created_at, CURRENT_TIMESTAMP) >= DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 30 MINUTE)

SELECT id, task_id, task_type, session_id, run_id, turn_id, status, attempt_count,
       failure_code, failure_message, input_ref, output_ref, created_at, updated_at, completed_at
FROM agent_memory_task


        status = #{status}


ORDER BY created_at DESC, id DESC
LIMIT #{limit}
